-- Replace the original Naughty & Nice catalog with the more suggestive rewrite.
delete from public.game_content
where pack_id = (select p.id from public.game_packs p join public.games g on g.id = p.game_id where g.slug = 'signal-spectrum' and p.slug = 'naughty');

with source(cards) as (values ($$Play it cool|Make the first move~Cheeky text|Send a risky photo~Slow dance|Dance against me~Eye contact|Lip bite~Kiss hello|Kiss goodbye~Sweet compliment|Dirty compliment~Hold hands|Hold me closer~First date|Last call~Romantic dinner|Midnight rendezvous~Flirt across the room|Pull me into a corner~Secret crush|Open invitation~Stay in|Sneak out together~Champagne toast|Champagne shower~Love song|Bedroom playlist~Candlelight|Lights off~Soft smile|Hungry stare~Playful dare|Private challenge~Long look|Slow undress~Voice note|Breathy voicemail~Goodnight kiss|Do not let me sleep~Handwritten note|Lipstick message~Cute nickname|Name whispered slowly~First move|Take control~Shy grin|Confident smirk~Brush my hand|Trace my skin~Sit beside me|Sit on my lap~Leave space|Close the distance~Ask nicely|Tell me what you want~Keep it sweet|Make it filthy~One more drink|One more kiss~Favorite outfit|Nothing but confidence~Silk blouse|Open shirt~Little black dress|Red-hot lingerie~Buttoned collar|Loose tie~High heels|Bare feet~Fresh sheets|Rumpled sheets~Perfume|Scent on my pillow~Lip gloss|Lipstick on my neck~Soft robe|Borrowed shirt~Elegant updo|Messy hair~New underwear|Something lacy~Suit and tie|Shirt on the floor~Favorite sweater|No sweater at all~Raincoat|Rain-soaked clothes~Morning coffee|Morning temptation~Hotel lobby|Hotel room~Corner booth|Back booth~Rooftop drinks|Balcony after dark~Guest room|Master bedroom~Locked door|Do not disturb~Window seat|Fogged-up window~Warm bath|Shared shower~Candlelit tub|Steamy mirror~Slow morning|No sleep tonight~Early checkout|Late checkout~Private balcony|Private balcony door~City lights|Curtains closed~Quiet hotel|Thin hotel walls~Room service|Midnight snack in bed~Fresh towels|Towel drop~Weekend away|One-night escape~Pack light|Pack something daring~Road trip|Pulled-over kiss~Beach walk|Beach after dark~Poolside drink|Poolside secret~Cabin fireplace|Cabin bedroom~Tent camping|Sleeping bag for two~Late-night drive|Park somewhere quiet~Backseat conversation|Backseat distraction~The spare key|The locked suite~Elevator glance|Elevator corner~Stairwell kiss|Rooftop rendezvous~Parking-lot goodbye|Drive home together~Last train|First train~Midnight snack|Midnight feast~Order dessert|Feed me dessert~Share a straw|Share a secret~One bite|One taste~Cherry on top|Cherry between us~Chocolate fondue|Chocolate on skin~Whipped cream|No napkins~Red wine|Wine on the sheets~Sparkling water|Spiked punch~Sweet tooth|Dangerous appetite~Kitchen dance|Kitchen counter~Cooking together|Distracting the chef~Apron strings|Untied apron~Flour on my nose|Hands on my waist~Dish duty|Shower duty~Movie night|Skip the movie~Rom-com|Steamy thriller~Shared blanket|Shared heat~Couch cuddle|Couch make-out~Remote control|No distractions~Pause the movie|Turn off the screen~Whispered clue|Whispered fantasy~Inside joke|Private code~Secret signal|Open invitation~Text me later|Come over now~Typing bubbles|Photo attachment~Read receipt|Seen at midnight~Good morning text|Come back to bed~Voice call|Video call~Flirty meme|Flirty selfie~Delete the chat|Save the chat~Heart emoji|Eggplant emoji~Kiss mark|Fingerprints~One line of lipstick|A whole trail of lipstick~Neck kiss|Neck kisses~Forehead kiss|Kiss everywhere else~Slow kiss|Breathless kiss~Peck on the cheek|Kiss me properly~Hands above the waist|Hands with permission~Fingers intertwined|Fingers wandering~Arm around me|Pull me in~Back rub|Massage oil~Shoulder rub|Lower back touch~Hair brush|Hair tug~Whisper in my ear|Talk dirty to me~Call me beautiful|Call me irresistible~Make me laugh|Make me blush~Keep me guessing|Tell me exactly~Ask permission|Give permission~Green light|Red-hot light~Safe word|Safeword check-in~Playful teasing|Relentless teasing~Slow burn|No patience~Take your time|Do not make me wait~One kiss|Keep going~Almost kiss|Finally kiss~Close call|Caught staring~Doorbell rings|Ignore the doorbell~Neighbors nearby|No one can hear us~Public flirt|Private scandal~Restaurant table|Under the table~Dance floor|Dark hallway~Office crush|After-hours office~Work trip|Work trip with benefits~Friends with chemistry|Friends with benefits~Old flame|New temptation~Second date|One-night mistake~Dating app match|Match in person~Stranger at the bar|Regular at the bar~Mystery guest|Familiar lover~Roleplay|Stay in character~Costume party|Costume comes off~Truth or dare|Dare with consequences~Never have I ever|Tell me everything~Would you rather|You choose~Blindfold|Trust me~Handcuffs|Hands above your head~Silk tie|Tied to the bedpost~Feather tease|Fingertip tease~Ice cube|Warm breath~Scented candle|Melted wax~Music low|Music off~Lights dim|Lights out~Mirror glance|Watch us~Camera shy|Polaroid proof~Keep it private|Leave a souvenir~One secret|No secrets tonight~Sweet talk|Dirty talk~Romantic fantasy|Naughty fantasy~Take the lead|Give up control~Switch roles|Stay in charge~Slow tease|Strip tease~Fully dressed|Barely dressed~Under the covers|On top of the covers~Good behavior|Very bad behavior~Be good|Make me behave~Kiss and tell|Never tell~Morning after|No regrets~Stay for breakfast|Stay until dinner~One more night|Move in tonight~Close friends|Closer lovers~Soft landing|Worth the trouble~Late spark|Full blaze~See you soon|Do not leave yet$$)), expanded as (
  select p.id as pack_id, entry.card, entry.ordinality::integer as sort_order
  from source s
  join public.games g on g.slug = 'signal-spectrum'
  join public.game_packs p on p.game_id = g.id and p.slug = 'naughty'
  cross join lateral unnest(string_to_array(s.cards, '~')) with ordinality as entry(card, ordinality)
), inserted as (
  insert into public.game_content(game_id, pack_id, content_type, payload, sort_order, is_published)
  select g.id, e.pack_id, 'wavelength-spectrum',
    jsonb_build_object('id', 'naughty-' || lpad(e.sort_order::text, 2, '0'), 'left', split_part(e.card, '|', 1), 'right', split_part(e.card, '|', 2), 'tags', jsonb_build_array('naughty')),
    e.sort_order, true
  from expanded e join public.games g on g.slug = 'signal-spectrum'
  returning id, pack_id
)
insert into public.wavelength_question_tags(content_id, pack_id)
select id, pack_id from inserted;
